mapper.insert:
/* 카카오 검색 결과 저장 : 카테고리·사용 여부는 기존 값 유지, 수정일시는 값이 바뀔 때만 자동 갱신 */ INSERT INTO PLC (PLC_CLSF_CD, PLC_SRC_CD, PLC_CONM, PLC_ADDR, RPRS_TELNO, KAKAO_PLC_ID, KAKAO_URL_PATH, PLC_LAT, PLC_LOT, USE_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) VALUES
(#{place.plcClsfCd}, #{place.plcSrcCd}, #{place.plcConm}, #{place.plcAddr}, #{place.rprsTelno}, #{place.kakaoPlcId}, #{place.kakaoUrlPath}, #{place.plcLat}, #{place.plcLot}, 'Y', NOW(), NOW(), 'SYSTEM', 'SYSTEM')
ON DUPLICATE KEY UPDATE PLC_CONM = VALUES(PLC_CONM) , PLC_ADDR = VALUES(PLC_ADDR) , RPRS_TELNO = VALUES(RPRS_TELNO) , KAKAO_URL_PATH = VALUES(KAKAO_URL_PATH) , PLC_LAT = VALUES(PLC_LAT) , PLC_LOT = VALUES(PLC_LOT)

mapper.select:
/* 사용 중인 장소 존재 여부 */
SELECT EXISTS (SELECT 1
                 FROM PLC P
                WHERE P.PLC_SN = #{plcSn}
                  AND P.USE_YN = 'Y')
